// Paket latihan buatan sendiri (soal orisinal), dikelompokkan per kategori:
//   indonesia     – gaya OSN/KSN SD
//   internasional – gaya SEAMO / Kangaroo / SASMO
//   standar       – soal biasa sesuai kurikulum, bukan olimpiade
// Setiap soal: q(kelas, tingkat, [topik id,en,zh], kunci, [id], [en], [zh], visual)
// dengan setiap bahasa = [pertanyaan, [jawaban benar, pengecoh, pengecoh, pengecoh], [langkah pembahasan...]].
// Jawaban benar selalu ditulis pertama; q() memindahkannya ke posisi huruf kunci.
// visual: objek gambar bantu, atau fungsi (bahasa) => objek bila labelnya bergantung bahasa.

const HURUF = ["A", "B", "C", "D"];
const q = (kelas, tingkat, topik, kunci, id, en, zh, visual) => {
  const pindah = ([tanya, opsi, langkah]) => {
    const o = opsi.slice(1);
    o.splice(HURUF.indexOf(kunci), 0, opsi[0]);
    return [tanya, o.map(String), langkah];
  };
  return { kelas, tingkat, topik, kunci, teks: { id: pindah(id), en: pindah(en), zh: pindah(zh) }, visual };
};
const f = (L) => (n) => n.toLocaleString(L === "id" ? "id-ID" : "en-US");
const d = (L) => (s) => (L === "id" ? String(s).replace(".", ",") : String(s));
const kel = (x, sampai) => Array.from({ length: Math.floor(sampai / x) }, (_, i) => x * (i + 1));
const fak = (n) => Array.from({ length: n }, (_, i) => i + 1).filter((v) => n % v === 0);
const rentang = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);

